mapper.select:
select `a`.*,d.drug_name from `alarm` a   left join `drug` d on a.drug_id = d.id
   where 1=1
   
       and `a`.id = #{id}
   
    
        and a.drug_id = #{drugId}
    
    
        and a.status = #{status}
    
    
        and d.drug_name like concat('%',#{drugName},'%')
    
    order by `a`.create_time desc
